17	// Fix 1 (final whole-branch review): explore mode's flagship feature — the
18	// clustered library map — must be reachable no matter what the now-playing
19	// poll is doing. These two states used to be full-screen early returns that
20	// replaced the map entirely, which meant BrowseLibraryButton and
21	// LibraryLoadingBadge only existed once something was playing. Both status
22	// messages are now a small overlay on top of the (always-rendered) map
23	// instead. "error" gets the same treatment as "idle": every case that lands
24	// here is an unrecognized *poll* error (classifyPollError already routes
25	// TOKEN_EXPIRED to a silent refresh and RATE_LIMITED to a retry) — never a
26	// hard auth failure — and the library-resolution loop is independent of the
27	// now-playing poll, so there's no reason a flaky currently-playing request
28	// should block browsing an already-fetched library.
29	const STATUS_OVERLAY_STYLE = {
30	  position: "fixed",
31	  top: "50%",
32	  left: "50%",
33	  transform: "translate(-50%, -50%)",
34	  zIndex: 900,
35	  padding: "16px 24px",
36	  textAlign: "center",
37	  // Nothing inside this overlay is interactive (just a message), and it now
38	  // sits on top of the always-rendered map — without this it swallows
39	  // clicks on any cluster/marker underneath it in explore mode while
40	  // idle/error.
41	  pointerEvents: "none",
42	  ...overlayCardStyle,
43	};
44	
45	// Fallback location for the scope warning / a control error when there's no
46	// NowPlayingCard to host the message (see displayMessage below). Mirrors
47	// NowPlayingCard's own message-slot styling (top-right, MUTED, 12px) so it
48	// reads as the same kind of notice.
49	//
50	// `color: MUTED` must come AFTER the `...overlayCardStyle` spread —
51	// overlayCardStyle sets `color: TEXT` (white), and object spread applies in
52	// source order, so putting MUTED first was silently overridden by white.
53	const STANDALONE_MESSAGE_STYLE = {
54	  position: "fixed",
55	  top: 16,
56	  right: 16,
57	  zIndex: 1000,
58	  padding: "10px 16px",
59	  fontSize: 12,
60	  textAlign: "center",
61	  ...overlayCardStyle,
62	  color: MUTED,
63	};
