1	import { Redis } from "@upstash/redis";
2	
3	const NOT_FOUND_TTL_SECONDS = 60 * 60 * 24 * 30; // 30 days
4	// server/geocode.js picks mbData.artists[0] from a fuzzy, undisambiguated
5	// MusicBrainz name search, so a wrong match for a common artist name is
6	// expected occasionally. Without a TTL that bad location would be cached
7	// forever, fixable only by hand in the Upstash console. 180 days bounds the
8	// damage while still making the cache effective for its purpose.
9	const RESOLVED_TTL_SECONDS = 60 * 60 * 24 * 180; // 180 days
10	
11	// The Vercel Marketplace Upstash integration injects credentials under a
12	// `REDIS_` prefix (`REDIS_KV_REST_API_URL` / `REDIS_KV_REST_API_TOKEN`), not
13	// either pair `Redis.fromEnv()` looks for (`UPSTASH_REDIS_REST_*` or
14	// `KV_REST_API_*`). Do not "simplify" this to `Redis.fromEnv()` — it will
15	// silently fail to authenticate in production. Uses the read-write token
16	// because the throttle lock does `SET NX PX`.
17	export const createRedisClient = () =>
18	  new Redis({
19	    url: process.env.REDIS_KV_REST_API_URL,
20	    token: process.env.REDIS_KV_REST_API_TOKEN,
21	  });
22	
23	export async function getCachedArtist(redis, artistId) {
24	  const value = await redis.get(`geo:${artistId}`);
25	  return value ?? null;
26	}
27	
28	export async function setCachedArtist(redis, artistId, value) {
29	  const ttlSeconds =
30	    value.status === "not_found" ? NOT_FOUND_TTL_SECONDS : RESOLVED_TTL_SECONDS;
31	  await redis.set(`geo:${artistId}`, value, { ex: ttlSeconds });
32	}
33	
34	export async function tryAcquireThrottle(redis, service, minIntervalMs) {
35	  const result = await redis.set(`throttle:${service}`, "1", {
36	    nx: true,
37	    px: minIntervalMs,
38	  });
39	  return result !== null;
40	}
