4	// Cancellable delay: rejects immediately (or as soon as `signal` aborts)
5	// instead of resolving, so a stale throttled-retry timer never fires a
6	// request for a loop whose effect has already been cleaned up.
7	function delay(ms, signal) {
8	  return new Promise((resolve, reject) => {
9	    if (signal.aborted) {
10	      reject(new DOMException("Aborted", "AbortError"));
11	      return;
12	    }
13	    const id = setTimeout(resolve, ms);
14	    signal.addEventListener(
15	      "abort",
16	      () => {
17	        clearTimeout(id);
18	        reject(new DOMException("Aborted", "AbortError"));
19	      },
20	      { once: true },
21	    );
22	  });
23	}
24	
25	// Sequential resolution loop, one in-flight /api/geocode call at a time. Runs
26	// at app boot (keyed on token) regardless of whether explore mode is visible,
27	// so the map has clustered markers ready by the time the user opens it.
28	export function useLibraryArtists(token) {
29	  const [artists, setArtists] = useState([]);
30	  const [resolvedCount, setResolvedCount] = useState(0);
31	  const [total, setTotal] = useState(0);
32	  const [scopeMissing, setScopeMissing] = useState(false);
33	  // Artists whose /api/geocode call failed for backend/network reasons
34	  // (see resolveArtist below) — tracked separately from resolvedCount so a
35	  // failure is never indistinguishable from a legitimate not_found.
36	  const [failedCount, setFailedCount] = useState(0);
37	  const mountedRef = useRef(true);
38	
39	  useEffect(() => {
40	    mountedRef.current = true;
41	    return () => {
42	      mountedRef.current = false;
43	    };
44	  }, []);
45	
46	  useEffect(() => {
47	    if (!token) return;
48	
49	    let cancelled = false;
50	    // One controller per effect run (i.e. per token). Its cleanup aborts
51	    // whatever /api/geocode request is in flight and cancels any pending
52	    // throttled-retry timer, so a token change (e.g. the routine
53	    // TOKEN_EXPIRED refresh in MapView.jsx) can never leave a stale request
54	    // racing the new loop's first request — at most one request is ever
55	    // in flight across a token change.
56	    const controller = new AbortController();
57	    const isLive = () => !cancelled && mountedRef.current;
58	
59	    function updateArtist(id, patch) {
60	      setArtists((prev) =>
61	        prev.map((a) => (a.id === id ? { ...a, ...patch } : a)),
62	      );
63	    }
64	
65	    // Resolves one artist, retrying in place on "throttled" until it gets a
66	    // terminal result. Never advances resolvedCount for a throttled retry.
67	    async function resolveArtist(artist) {
68	      for (;;) {
69	        if (!isLive()) return;
70	
71	        let result;
72	        try {
73	          const response = await fetch("/api/geocode", {
74	            method: "POST",
75	            headers: { "Content-Type": "application/json" },
76	            body: JSON.stringify({
77	              artistId: artist.id,
78	              artistName: artist.name,
79	            }),
80	            signal: controller.signal,
81	          });
82	          // Non-200 (e.g. a raw 500 — api/geocode.js wraps its own Redis
83	          // calls and declares this as {status: "unavailable"}, but a
84	          // network hop between us and Vercel can still surface as some
85	          // other non-200, or 401/400/405) is treated as a resolution
86	          // failure for this artist rather than retried: retrying an outage
87	          // would spin the loop hot, and this artist isn't special. It is
88	          // NOT treated as "not_found" though — that's a legitimate
89	          // negative result from MusicBrainz/Nominatim, and this isn't one
90	          // (see the "unavailable" handling below). Only "throttled" (a 200
91	          // response) retries, since that's the server explicitly asking us
92	          // to wait, with a bounded backoff it names itself.
93	          result = response.ok
94	            ? await response.json()
95	            : { status: "unavailable" };
96	        } catch {
97	          // Covers both a genuine network failure (treated like a non-200
98	          // above) and this request being aborted by cleanup on a token
99	          // change — the isLive() check right below discards `result` in
100	          // the abort case, so it never gets marked unavailable or counted.
101	          result = { status: "unavailable" };
102	        }
103	
104	        if (!isLive()) return;
105	
106	        if (result.status === "throttled") {
107	          try {
108	            await delay(result.retryAfterMs, controller.signal);
109	          } catch {
110	            return; // aborted while waiting to retry — loop is dead, stop
111	          }
112	          continue;
113	        }
114	
115	        if (result.status === "unavailable") {
116	          // A backend/network failure, not a legitimate negative result.
117	          // Deliberately NOT counted in resolvedCount (see failedCount's
118	          // declaration) so an outage can never make the library look
119	          // "fully resolved" — LibraryLoadingBadge stays visible instead of
120	          // hiding on a false "done". Also deliberately NOT retried here
121	          // (that would spin the loop hot on a real outage); it simply
122	          // moves on, same as the rest of this loop's failure handling.
123	          updateArtist(artist.id, { status: "unavailable" });
124	          if (isLive()) setFailedCount((c) => c + 1);
125	          return;
126	        }
127	
128	        if (result.status === "resolved") {
129	          updateArtist(artist.id, {
130	            status: "resolved",
131	            lat: result.lat,
132	            lng: result.lng,
