import {
  acquireThrottle,
  createRedisClient,
  getThrottleRetryMs,
  recordLookupMetrics,
  releaseThrottleAfter,
} from "/Users/bert/github/sound-map/server/kv.js";

// Deliberately NOT "musicbrainz"/"nominatim" — this must not disturb the real
// throttle keys in production.
const SERVICE = "__selftest";
const KEY = `throttle:${SERVICE}`;
const redis = createRedisClient();

const check = (label, ok, detail) =>
  console.log(`${ok ? "PASS" : "FAIL"}  ${label}${detail ? ` — ${detail}` : ""}`);

await redis.del(KEY);

// 1. acquire
const token = await acquireThrottle(redis, SERVICE, 2200);
const ttlAfterAcquire = await redis.pttl(KEY);
check("acquire returns a token", Boolean(token), token);
check(
  "hold is ~2200ms",
  ttlAfterAcquire > 2000 && ttlAfterAcquire <= 2200,
  `pttl=${ttlAfterAcquire}`,
);

// 2. a second holder is refused
check("second acquire refused", (await acquireThrottle(redis, SERVICE, 2200)) === null);

// 3. retry hint reflects the real TTL
const hint = await getThrottleRetryMs(redis, SERVICE, 9999);
check("retry hint tracks pttl", hint > 0 && hint <= 2200, `${hint}ms`);

// 4. fencing: a stale token must not touch someone else's lock
const beforeStale = await redis.pttl(KEY);
const staleResult = await releaseThrottleAfter(redis, SERVICE, "not-my-token", 100);
const afterStale = await redis.pttl(KEY);
check(
  "stale token cannot shorten the lock",
  staleResult === false && afterStale > 1000,
  `pttl ${beforeStale} -> ${afterStale}`,
);

// 5. shorten with the real token
await releaseThrottleAfter(redis, SERVICE, token, 400);
const afterShorten = await redis.pttl(KEY);
check(
  "own token shortens the lock to ~400ms",
  afterShorten > 0 && afterShorten <= 400,
  `pttl=${afterShorten}`,
);

// 6. zero remainder deletes outright
await releaseThrottleAfter(redis, SERVICE, token, 0);
const exists = await redis.exists(KEY);
check("zero remainder deletes the lock", exists === 0);

// 7. metrics pipeline round-trips
await recordLookupMetrics(redis, {
  counters: { count: 1, totalMs: 123 },
  sample: { at: Date.now(), artist: "__selftest", ms: 123 },
});
const hash = await redis.hgetall("metrics:geocode");
const recent = await redis.lrange("metrics:geocode:recent", 0, 0);
check("metrics hash written", Number(hash?.count) === 1, JSON.stringify(hash));
check("metrics sample written", recent.length === 1, JSON.stringify(recent[0]));

// clean up everything this script created
await redis.del(KEY, "metrics:geocode", "metrics:geocode:recent");
console.log("\ncleaned up:", await redis.exists(KEY, "metrics:geocode", "metrics:geocode:recent"), "keys left");

